function switchView(view) { const settings = view === 'settings', team = view === 'team', aiProviders = view === 'ai-providers', media = view === 'media', campaigns = view === 'campaigns'; el('workspace-content').hidden = settings || team || aiProviders || media || campaigns; el('settings').hidden = !settings; el('ai-settings').hidden = !aiProviders || !(isAdmin || canManageWorkspace()); el('team').hidden = !team; el('media').hidden = !media; el('campaigns').hidden = !campaigns; if (media) { loadMediaJobs(); loadMediaLibrary(); } if (campaigns) { loadCampaigns(); renderCampaignChoices(); } document.querySelectorAll('.nav-tab').forEach(tab => tab.setAttribute('aria-selected', String(tab.dataset.view === view))); }
