function renderConnections() { const platforms = selectedPlatforms(); const targets = el('target-list'); const selectable = connections.filter(item => item.is_active && (!item.token_expires_at || new Date(item.token_expires_at) > new Date()) && platforms.includes(item.provider)); if (!platforms.length) { targets.replaceChildren(add('div', 'Choose at least one platform.', 'target-empty')); return; } if (!selectable.length) { targets.replaceChildren(add('div', 'No connected accounts for these platforms yet. Use the connection form to add them.', 'target-empty')); return; } const existing = new Set([...targets.querySelectorAll('input:checked')].map(input => input.value)); targets.replaceChildren(...selectable.map(item => { const label = document.createElement('label'); label.className = 'target-account'; const input = document.createElement('input'); input.type = 'checkbox'; input.value = item.id; input.dataset.provider = item.provider; input.checked = existing.has(String(item.id)); const copy = document.createElement('span'); copy.append(add('strong', item.display_name), add('small', `${item.provider} - ${item.external_account_id}`)); label.append(input, copy); return label; })); }
