async function load() { const response = await api('/api/dashboard'); if (!response.ok) return message('Could not load the workspace.', true); const data = await response.json(); const accountResult = await api('/api/connections'); const accounts = await accountResult.json(); connections = accounts.connections || []; renderConnections(); el('providers').replaceChildren(...data.providers.map(provider => { const row = document.createElement('div'); row.className = 'channel-row'; const activeCount = connections.filter(account => account.provider === provider.name && account.is_active).length; const alerts = connections.filter(account => account.provider === provider.name && ['expiring_soon', 'expired'].includes(account.health)).length; const copy = document.createElement('div'); copy.append(add('strong', provider.name), add('small', activeCount ? `${activeCount} connected destination${activeCount === 1 ? '' : 's'}${alerts ? ` · ${alerts} token${alerts === 1 ? '' : 's'} expiring or expired` : ''}` : 'No active destination')); const actions = document.createElement('div'); const status = add('span', provider.status, `channel-state${provider.status === 'ready' ? ' ready' : ''}`); actions.append(status); if (provider.oauth_available && canManageWorkspace()) { const connect = add('button', 'Connect', 'quiet'); connect.type = 'button'; connect.onclick = () => { location.href = `/api/social-oauth/${provider.name}/start`; }; actions.append(connect); } if (canManageWorkspace()) { const manage = add('button', activeCount ? 'Manage' : provider.oauth_available ? 'Manual' : 'Connect', 'quiet'); manage.type = 'button'; manage.onclick = () => openConnectionDialog(provider.name); actions.append(manage); } row.append(copy, actions); return row; })); renderPosts(data); }
const providerDefaultModels = {OpenAI:['gpt-5.6-sol'], OpenRouter:['openai/gpt-5.6-sol'], Kimi:['kimi-k3'], MiniMax:['MiniMax-M2.7'], 'Z.AI GLM':['glm-5.2']};
