const aiComposeChoices = document.createElement('div'); aiComposeChoices.className = 'form-grid'; aiComposeChoices.style.marginTop = '12px'; const aiComposeProvider = document.createElement('select'); aiComposeProvider.id = 'ai-compose-provider'; const aiComposeModel = document.createElement('select'); aiComposeModel.id = 'ai-compose-model'; const aiProviderLabel = document.createElement('label'); aiProviderLabel.htmlFor = aiComposeProvider.id; aiProviderLabel.textContent = 'AI provider'; aiProviderLabel.append(aiComposeProvider); const aiModelLabel = document.createElement('label'); aiModelLabel.htmlFor = aiComposeModel.id; aiModelLabel.textContent = 'Model'; aiModelLabel.append(aiComposeModel); aiComposeChoices.append(aiProviderLabel, aiModelLabel); el('ai-instruction').closest('div').before(aiComposeChoices);
