async function loadAiSettings() { const response = await api(aiScopeBase()); if (!response.ok) return; const result = await response.json(); aiConfigurations = result.providers || []; const list = el('ai-config-list'); list.replaceChildren(...aiConfigurations.map(item => { const card = document.createElement('article'); card.className = 'account-card'; const checked = item.models_checked_at ? ` · ${item.models_count} saved models` : ''; card.append(add('strong', item.name), add('small', `${item.model} · ${item.has_api_key ? 'API key saved' : 'Not connected'}${checked}`)); const actions = document.createElement('div'); actions.className = 'account-actions'; const edit = add('button', item.has_api_key ? 'Edit' : 'Configure', 'quiet'); edit.type = 'button'; edit.onclick = () => fillAiSettings(item.name); actions.append(edit); if (item.has_api_key) { const remove = add('button', 'Remove API key', 'quiet'); remove.type = 'button'; remove.onclick = async () => { if (!confirm(`Remove the saved ${item.name} API key and cached model list?`)) return; const removeResponse = await api(`${aiScopeBase()}/${encodeURIComponent(item.name)}/remove`, {method:'POST', headers:{'Content-Type':'application/json'}, body:'{}'}); const removeResult = await removeResponse.json(); message(removeResponse.ok ? `${item.name} API key removed.` : (removeResult.error || 'Could not remove API key.'), !removeResponse.ok); if (removeResponse.ok) { await loadAiSettings(); await loadAiProviders(); fillAiSettings(item.name); } }; actions.append(remove); } card.append(actions); return card; })); fillAiSettings(); }
async function uploadImage(file) { if (file.size > 5 * 1024 * 1024) throw new Error(`${file.name} is larger than 5 MB.`); const data = await new Promise((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result).split(',')[1]); reader.onerror = reject; reader.readAsDataURL(file); }); const response = await api('/api/uploads', {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({content_type:file.type, data})}); const result = await response.json(); if (!response.ok) throw new Error(result.error || 'Image upload failed.'); return result.url; }
el('image').onchange = event => { selectedFiles = [...event.target.files].slice(0, 10); if (event.target.files.length > 10) message('Only the first 10 images were selected.', true); renderMedia(); };
