el('connection-form').onsubmit = async event => { event.preventDefault(); const provider = el('connection-provider').value, tokenKey = provider === 'Telegram' ? 'bot_token' : provider === 'Discord' ? 'webhook_url' : 'access_token', accountId = el('connection-id').value.trim(), credential = provider === 'Discord' ? accountId : el('connection-token').value; const response = await api('/api/connections', {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({provider, display_name:el('connection-name').value.trim(), external_account_id:accountId, secrets:{[tokenKey]:credential}})}); const result = await response.json(); message(response.ok ? 'Destination connected. You can now select it in the composer.' : (result.error || 'Could not connect destination.'), !response.ok); if (response.ok) { el('connection-dialog').close(); load(); } };
el('password-form').onsubmit = async event => { event.preventDefault(); const response = await api('/api/me/password', {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({current_password:el('current-password').value, new_password:el('new-password').value})}); const result = await response.json(); if (!response.ok) return message(result.error || 'Could not change password.', true); csrfToken = result.csrf_token; event.target.reset(); message('Password changed. Other sessions were signed out.'); };
