el('ai-settings-provider').onchange = () => fillAiSettings(); el('ai-refresh-models').onclick = refreshAiModels; el('ai-settings-form').onsubmit = async event => { event.preventDefault(); const provider = el('ai-settings-provider').value; const response = await api(aiScopeBase(), {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({provider, model:el('ai-settings-model').value || providerDefaultModels[provider]?.[0] || '', api_key:el('ai-settings-key').value})}); const result = await response.json(); if (!response.ok) return message(result.error || 'Could not save AI provider.', true); el('ai-settings-key').value = ''; message(`${result.name} AI provider saved.`); await loadAiSettings(); await loadAiProviders(); fillAiSettings(provider); };
