let brandVoice = null;
const brandToggleWrap = document.createElement('label'); brandToggleWrap.id = 'brand-voice-toggle-row'; brandToggleWrap.style.cssText = 'display:flex; gap:8px; align-items:center; margin-top:10px'; brandToggleWrap.hidden = true;
