brandToggleWrap.append(brandToggle, document.createTextNode('Apply brand voice'));
el('ai-instruction').closest('div').after(brandToggleWrap);
const lines = value => value.split('\n').map(item => item.trim()).filter(Boolean);
const commas = value => value.split(',').map(item => item.trim()).filter(Boolean);
async function loadBrandVoice() { const response = await api('/api/workspaces/brand-voice'); if (!response.ok) return; const result = await response.json(); brandVoice = result.profile; brandToggleWrap.hidden = !result.configured; el('brand-voice').hidden = !(result.editable || result.configured); const profile = result.profile || {}; el('brand-tone').value = profile.tone || ''; el('brand-audience').value = profile.audience || ''; el('brand-visual-style').value = profile.visual_style || ''; el('brand-hashtags').value = (profile.hashtags || []).join(', '); el('brand-do').value = (profile.do_phrases || []).join('\n'); el('brand-dont').value = (profile.dont_phrases || []).join('\n'); el('brand-samples').value = (profile.sample_posts || []).join('\n'); for (const id of ['brand-tone','brand-audience','brand-visual-style','brand-hashtags','brand-do','brand-dont','brand-samples','brand-voice-clear']) el(id).disabled = !result.editable; }
async function saveBrandVoice(profile) { const response = await api('/api/workspaces/brand-voice', {method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({profile})}); const result = await response.json(); message(response.ok ? (profile ? 'Brand voice saved.' : 'Brand voice cleared.') : (result.error || 'Could not save the brand voice.'), !response.ok); if (response.ok) loadBrandVoice(); }
el('brand-voice-form').onsubmit = event => { event.preventDefault(); saveBrandVoice({tone: el('brand-tone').value.trim(), audience: el('brand-audience').value.trim(), visual_style: el('brand-visual-style').value.trim(), hashtags: commas(el('brand-hashtags').value), do_phrases: lines(el('brand-do').value), dont_phrases: lines(el('brand-dont').value), sample_posts: lines(el('brand-samples').value)}); };
el('brand-voice-clear').onclick = () => saveBrandVoice(null);

// -----------------------------------------------------------------------
// Campaigns: plan a brief into drafts. Nothing here schedules or publishes.
// -----------------------------------------------------------------------
function renderCampaignChoices() {
  const providerSelect = el('campaign-provider'); const previous = providerSelect.value;
  providerSelect.replaceChildren(...aiProviders.map(item => { const option = document.createElement('option'); option.value = item.name; option.textContent = item.name; return option; }));
  if (previous) providerSelect.value = previous;
  const chosen = aiProviders.find(item => item.name === providerSelect.value) || aiProviders[0];
  el('campaign-model').replaceChildren(...((chosen && chosen.models) || []).map(name => { const option = document.createElement('option'); option.value = name; option.textContent = name; return option; }));
  if (!el('campaign-platforms').childElementCount) {
    el('campaign-platforms').replaceChildren(...[...el('platforms').querySelectorAll('input')].map(source => {
      const label = document.createElement('label'); label.className = 'platform'; const input = document.createElement('input');
      input.type = 'checkbox'; input.value = source.value; label.append(input, add('span', source.value)); return label;
    }));
  }
}
el('campaign-provider').onchange = renderCampaignChoices;
async function loadCampaigns() {
  const response = await api('/api/campaigns'); if (!response.ok) return; const result = await response.json();
  const rows = (result.campaigns || []).map(campaign => { const row = document.createElement('div'); row.className = 'user-row'; row.append(add('span', `${campaign.name} - ${campaign.posts} draft${campaign.posts === 1 ? '' : 's'}`)); return row; });
  el('campaign-list').replaceChildren(...(rows.length ? rows : [add('p', 'No campaigns planned yet.', 'field-help')]));
}
el('campaign-form').onsubmit = async event => {
  event.preventDefault();
  const channels = [...el('campaign-platforms').querySelectorAll('input:checked')].map(input => input.value);
  if (!channels.length) return message('Choose at least one platform to plan for.', true);
  const button = event.target.querySelector('button'); button.disabled = true; message('Planning campaign…');
  try {
    const response = await api('/api/campaigns', {method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({
      name: el('campaign-name').value.trim(), brief: el('campaign-brief').value.trim(), cadence: el('campaign-cadence').value.trim(),
      channels, count: Number(el('campaign-count').value), provider: el('campaign-provider').value, model: el('campaign-model').value })});
    const result = await response.json();
    if (!response.ok) throw new Error(result.error || 'Could not plan the campaign.');
    message(`${result.created} draft${result.created === 1 ? '' : 's'} created. Review them in the workspace before scheduling.`);
    el('campaign-name').value = ''; el('campaign-brief').value = ''; loadCampaigns(); load();
  } catch (error) { message(error.message || 'Could not plan the campaign.', true); } finally { button.disabled = false; }
};

const aiGenerateLabel = el('ai-generate').textContent; function setAiGenerating(button, pending) { button.disabled = pending; button.setAttribute('aria-busy', String(pending)); button.replaceChildren(); if (pending) { const spinner = document.createElement('span'); spinner.className = 'button-spinner'; spinner.setAttribute('aria-hidden', 'true'); button.append(spinner, document.createTextNode('Generating…')); } else button.textContent = aiGenerateLabel; }
el('ai-generate').onclick = async () => { const button = el('ai-generate'), channels = selectedPlatforms(), provider = aiProviders.find(item => item.name === aiComposeProvider.value), model = aiComposeModel.value; if (!channels.length) return message('Choose at least one destination before generating copy.', true); if (!provider || !model) return message('An administrator must configure an AI provider and model first.', true); setAiGenerating(button, true); message('Generating post copy…'); try { const response = await api('/api/ai/generate', {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({provider:provider.name, model, instruction:el('ai-instruction').value.trim(), draft:el('body').value, channels, apply_brand_voice: brandToggle.checked})}); const result = await response.json(); if (!response.ok) throw new Error(result.error || 'Could not generate post copy.'); el('body').value = result.copy; message('AI copy added to the composer. Review it before saving.'); } catch (error) { message(error.message || 'Could not generate post copy.', true); } finally { setAiGenerating(button, false); } };
