async function loadOrganizations() { const response = await api('/api/organizations'); if (!response.ok) return; const result = await response.json(); const organizations = result.organizations || []; el('organization-list').replaceChildren(...organizations.map(organization => { const row = document.createElement('div'); row.className = 'user-row'; row.append(add('span', `${organization.name} - ${organization.role}`)); const open = add('button', 'Open'); open.type = 'button'; open.onclick = () => selectOrganization(organization); row.append(open); return row; })); if (!organizations.length) el('organization-list').replaceChildren(add('p', 'No organizations yet.', 'field-help')); if (activeOrganization && !organizations.some(item => item.id === activeOrganization.id)) selectOrganization(null); }
async function selectOrganization(organization) { activeOrganization = organization; el('organization-detail').hidden = !organization; if (!organization) return; el('organization-detail-title').textContent = organization.name; const manages = organization.role === 'owner' || organization.role === 'admin'; el('organization-workspace-form').hidden = !manages; el('organization-member-form').hidden = !manages; await loadOrganizationDetail(); }
async function loadOrganizationDetail() { if (!activeOrganization) return; const [workspaces, members] = await Promise.all([api(`/api/organizations/${activeOrganization.id}/workspaces`), api(`/api/organizations/${activeOrganization.id}/members`)]); if (workspaces.ok) { const result = await workspaces.json(); el('organization-workspaces').replaceChildren(...(result.workspaces || []).map(workspace => { const row = document.createElement('div'); row.className = 'user-row'; row.append(add('span', `${workspace.name} - ${workspace.plan}`)); return row; })); if (!(result.workspaces || []).length) el('organization-workspaces').replaceChildren(add('p', 'No workspaces in this organization yet.', 'field-help')); } if (members.ok) { const result = await members.json(); el('organization-members').replaceChildren(...(result.members || []).map(member => { const row = document.createElement('div'); row.className = 'user-row'; row.append(add('span', `${member.username} - ${member.role}`)); return row; })); } }
el('organization-form').onsubmit = async event => { event.preventDefault(); const response = await api('/api/organizations', {method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({name: el('organization-name').value.trim()})}); const result = await response.json(); message(response.ok ? 'Organization created.' : (result.error || 'Could not create the organization.'), !response.ok); if (response.ok) { event.target.reset(); await loadOrganizations(); selectOrganization({...result}); } };
el('organization-workspace-form').onsubmit = async event => { event.preventDefault(); if (!activeOrganization) return; const response = await api(`/api/organizations/${activeOrganization.id}/workspaces`, {method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({name: el('organization-workspace-name').value.trim()})}); const result = await response.json(); message(response.ok ? 'Workspace created in the organization.' : (result.error || 'Could not create the workspace.'), !response.ok); if (response.ok) { event.target.reset(); loadOrganizationDetail(); } };
