async function loadMembers() { const response = await api('/api/workspaces/members'); if (!response.ok) return; const result = await response.json(); el('member-list').replaceChildren(...(result.members || []).map(member => { const row = document.createElement('div'); row.className = 'user-row'; row.append(add('span', `${member.username} - ${member.role}${member.is_active ? '' : ' (disabled account)'}`)); if (member.role !== 'owner' && member.username !== currentUser) { const actions = document.createElement('div'); actions.style.cssText = 'display:flex; gap:8px; align-items:center'; const roleSelect = document.createElement('select'); roleSelect.style.width = 'auto'; ['viewer', 'editor', 'admin'].forEach(role => roleSelect.add(new Option(role, role, false, role === member.role))); roleSelect.setAttribute('aria-label', `Role for ${member.username}`); roleSelect.onchange = async () => { const changeResponse = await api(`/api/workspaces/members/${member.user_id}/role`, {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({role:roleSelect.value})}); const changeResult = await changeResponse.json(); message(changeResponse.ok ? 'Member role updated.' : (changeResult.error || 'Could not change the member role.'), !changeResponse.ok); loadMembers(); }; const removeMember = add('button', 'Remove', 'quiet'); removeMember.onclick = async () => { if (!confirm(`Remove ${member.username} from this workspace? Their personal workspace is not affected.`)) return; const removeResponse = await api(`/api/workspaces/members/${member.user_id}/remove`, {method:'POST', headers:{'Content-Type':'application/json'}, body:'{}'}); const removeResult = await removeResponse.json(); message(removeResponse.ok ? 'Member removed from the workspace.' : (removeResult.error || 'Could not remove the member.'), !removeResponse.ok); loadMembers(); }; actions.append(roleSelect, removeMember); row.append(actions); } return row; })); }
el('member-form').onsubmit = async event => { event.preventDefault(); const response = await api('/api/workspaces/members', {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({username:el('member-username').value.trim(), role:el('member-role').value})}); const result = await response.json(); message(response.ok ? 'Member added to the workspace.' : (result.error || 'Could not add the member.'), !response.ok); if (response.ok) { event.target.reset(); loadMembers(); } };
async function loadInvites() { const response = await api('/api/workspaces/invitations'); if (!response.ok) return; const result = await response.json(); el('invite-list').replaceChildren(...(result.invitations || []).map(invite => { const row = document.createElement('div'); row.className = 'user-row'; row.append(add('span', `${invite.email} - ${invite.role}${invite.expired ? ' (expired)' : ` - expires ${new Date(invite.expires_at).toLocaleDateString()}`}`)); const revoke = add('button', 'Revoke', 'quiet'); revoke.onclick = async () => { const revokeResponse = await api(`/api/workspaces/invitations/${invite.id}/revoke`, {method:'POST', headers:{'Content-Type':'application/json'}, body:'{}'}); const revokeResult = await revokeResponse.json(); message(revokeResponse.ok ? 'Invitation revoked.' : (revokeResult.error || 'Could not revoke the invitation.'), !revokeResponse.ok); loadInvites(); }; row.append(revoke); return row; })); }
el('invite-form').onsubmit = async event => { event.preventDefault(); const response = await api('/api/workspaces/invitations', {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({email:el('invite-email').value.trim(), role:el('invite-role').value})}); const result = await response.json(); if (!response.ok) return message(result.error || 'Could not create the invitation.', true); event.target.reset(); const linkInput = document.createElement('input'); linkInput.readOnly = true; linkInput.value = result.invite_url; linkInput.onfocus = () => linkInput.select(); el('invite-result').hidden = false; el('invite-result').replaceChildren(add('span', result.email_sent ? 'Invitation emailed. Backup link:' : 'Email is not configured — share this link:'), linkInput); message('Invitation created.'); loadInvites(); };
const mediaAspects = { image:['1:1', '3:2', '2:3', '16:9', '9:16'], video:['16:9', '9:16', '1:1'] };
function syncMediaAspects() { el('media-aspect').replaceChildren(...mediaAspects[el('media-kind').value].map(aspect => new Option(aspect, aspect))); }
function syncMediaProviders() { const current = el('media-provider').value; el('media-provider').replaceChildren(...aiProviders.map(item => new Option(item.name, item.name))); if (aiProviders.some(item => item.name === current)) el('media-provider').value = current; }
async function loadMediaJobs() { const response = await api('/api/media/jobs'); if (!response.ok) return; const result = await response.json(); el('media-jobs').replaceChildren(...(result.jobs || []).map(job => { const row = document.createElement('div'); row.className = 'user-row'; const summary = `#${job.id} ${job.kind} · ${job.status}${job.status === 'running' ? ` ${job.progress}%` : ''} · review: ${job.moderation} · ${job.prompt.slice(0, 70)}${job.prompt.length > 70 ? '…' : ''}`; const copy = document.createElement('span'); copy.textContent = summary; if (job.error) copy.append(add('span', ` — ${job.error}`, 'post-error')); row.append(copy); const actions = document.createElement('div'); actions.style.cssText = 'display:flex; gap:8px; align-items:center'; if (job.result_url) { const view = document.createElement('a'); view.href = job.result_url; view.target = '_blank'; view.rel = 'noopener'; view.textContent = 'View'; actions.append(view); } if (canManageWorkspace() && job.status === 'succeeded' && job.moderation === 'pending') { ['approved', 'rejected'].forEach(decision => { const button = add('button', decision === 'approved' ? 'Approve' : 'Reject', decision === 'approved' ? 'secondary' : 'quiet'); button.onclick = async () => { const reviewResponse = await api(`/api/media/jobs/${job.id}/review`, {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({decision})}); const reviewResult = await reviewResponse.json(); message(reviewResponse.ok ? `Media ${decision}.` : (reviewResult.error || 'Could not review media.'), !reviewResponse.ok); loadMediaJobs(); loadMediaLibrary(); }; actions.append(button); }); } row.append(actions); return row; })); }
async function loadMediaLibrary() { const response = await api('/api/media/library'); if (!response.ok) return; const result = await response.json(); el('media-library').replaceChildren(...(result.assets || []).map(asset => { const figure = document.createElement('figure'); figure.style.width = 'auto'; figure.style.height = 'auto'; if (asset.kind === 'image') { const image = document.createElement('img'); image.src = asset.result_url; image.alt = asset.prompt.slice(0, 80); figure.append(image); } else { const link = document.createElement('a'); link.href = asset.result_url; link.target = '_blank'; link.rel = 'noopener'; link.textContent = `▶ video #${asset.id}`; figure.append(link); } if (canEditWorkspace() && asset.kind === 'image') { const use = add('button', '+', 'secondary'); use.type = 'button'; use.title = 'Attach to the composer'; use.setAttribute('aria-label', `Attach library image ${asset.id} to the composer`); use.onclick = () => { if (selectedLibrary.includes(asset.result_url)) return message('That image is already attached.', true); selectedLibrary.push(asset.result_url); renderMedia(); switchView('workspace'); message('Library image attached to the composer.'); }; figure.append(use); } return figure; })); }
el('media-kind').onchange = syncMediaAspects; syncMediaAspects();
el('media-form').onsubmit = async event => { event.preventDefault(); const response = await api('/api/media/jobs', {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({kind:el('media-kind').value, prompt:el('media-prompt').value.trim(), aspect_ratio:el('media-aspect').value, style:el('media-style').value.trim(), provider:el('media-provider').value, model:el('media-model').value.trim()})}); const result = await response.json(); message(response.ok ? 'Media generation queued. Progress appears below.' : (result.error || 'Could not queue the media job.'), !response.ok); if (response.ok) { el('media-prompt').value = ''; loadMediaJobs(); } };
setInterval(() => { if (!el('media').hidden) loadMediaJobs(); }, 8000);
async function loadOverview() { const response = await api('/api/workspaces/status'); if (!response.ok) return; const status = await response.json(); const withLimit = (used, name) => status.limits && status.limits[name] != null ? `${used} / ${status.limits[name]}` : String(used); const parts = [`Plan: ${status.plan}`, `Members: ${withLimit(status.members, 'members')}`, `Posts this month: ${withLimit(status.usage.posts_created, 'posts_per_month')}`, `AI copy: ${withLimit(status.usage.ai_generations, 'ai_generations_per_month')}`, `AI media: ${withLimit(status.usage.ai_media, 'ai_media_per_month')}`, `Storage: ${(status.usage.storage_bytes / 1048576).toFixed(1)} MB${status.limits && status.limits.storage_mb != null ? ` / ${status.limits.storage_mb} MB` : ''}`, `Channels: ${status.connection_health.active} healthy, ${status.connection_health.expiring_soon} expiring, ${status.connection_health.expired} expired`]; if (status.ai_monthly_cap != null) { parts.push(`AI cap: ${status.ai_monthly_cap}/month`); el('ai-cap').value = status.ai_monthly_cap; } el('workspace-overview').textContent = parts.join(' · '); }
el('workspace-export').onclick = () => { location.href = '/api/workspaces/export'; };
el('workspace-delete').onclick = async () => { if (!confirm(`Delete the workspace "${activeWorkspace?.name}"? Its channel connections are disabled and queued posts are unscheduled.`)) return; const response = await api('/api/workspaces/delete', {method:'POST', headers:{'Content-Type':'application/json'}, body:'{}'}); const result = await response.json(); if (!response.ok) return message(result.error || 'Could not delete the workspace.', true); location.href = '/'; };
el('workspace-switcher').onchange = async event => { const response = await api('/api/me/workspace', {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({workspace_id:Number(event.target.value)})}); if (response.ok) { location.reload(); return; } const result = await response.json(); message(result.error || 'Could not switch workspace.', true); };
el('new-workspace').onclick = async () => { const name = prompt('Name the new workspace'); if (!name || !name.trim()) return; const response = await api('/api/workspaces', {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({name:name.trim()})}); if (response.ok) { location.reload(); return; } const result = await response.json(); message(result.error || 'Could not create the workspace.', true); };
async function start() { timezoneOptions(el('timezone')); timezoneOptions(el('settings-timezone')); timezoneOptions(el('new-user-timezone')); const setup = await fetch('/api/setup-status').then(response => response.json()); const session = await fetch('/api/session'); const inviteToken = location.pathname === '/invite' ? new URLSearchParams(location.search).get('token') || '' : '';
if (inviteToken) { el('auth').hidden = false; const inviteResponse = await fetch(`/api/invitations/${encodeURIComponent(inviteToken)}`); const invite = await inviteResponse.json(); if (!inviteResponse.ok) { el('auth-title').textContent = 'Invitation unavailable'; el('auth-form').hidden = true; el('auth-message').textContent = invite.error || 'This invitation is invalid or expired.'; return; } el('auth-title').textContent = `Join ${invite.workspace}`; if (session.ok) { const current = await session.json(); csrfToken = current.csrf_token; el('auth-form').hidden = true; document.querySelector('#auth .field-help').textContent = `You are signed in as ${current.username}. Accept to join ${invite.workspace} as ${invite.role}.`; const join = add('button', 'Accept invitation', 'primary'); join.onclick = async () => { const response = await api(`/api/invitations/${encodeURIComponent(inviteToken)}/accept`, {method:'POST', headers:{'Content-Type':'application/json'}, body:'{}'}); const result = await response.json(); if (!response.ok) { el('auth-message').textContent = result.error || 'Could not accept the invitation.'; return; } location.href = '/'; }; el('auth-message').before(join); return; } el('auth-submit').textContent = 'Create account & join'; document.querySelector('#auth .field-help').textContent = `You were invited as ${invite.role} (${invite.email}). Choose a username and password, or sign in first and reopen this link.`; el('auth-form').onsubmit = async event => { event.preventDefault(); const response = await fetch(`/api/invitations/${encodeURIComponent(inviteToken)}/accept`, {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({username:el('username').value.trim(), password:el('password').value})}); const result = await response.json(); if (!response.ok) { el('auth-message').textContent = result.error || 'Could not accept the invitation.'; return; } location.href = '/'; }; return; }
if (session.ok) { const current = await session.json(); csrfToken = current.csrf_token; currentUser = current.username; isAdmin = current.role === 'admin'; workspaces = current.workspaces || []; activeWorkspace = current.workspace; workspaceRole = current.workspace?.role || ''; timezoneOptions(el('timezone'), current.timezone); timezoneOptions(el('settings-timezone'), current.timezone); timezoneOptions(el('new-user-timezone'), current.timezone); el('signature').value = current.signature || ''; el('workspace').hidden = false; el('app-nav').hidden = false; el('logout').hidden = false; const switcher = el('workspace-switcher'); switcher.replaceChildren(...workspaces.map(space => new Option(space.role === 'owner' ? space.name : `${space.name} (${space.role})`, space.id))); if (activeWorkspace) switcher.value = String(activeWorkspace.id); switcher.hidden = workspaces.length < 2; el('new-workspace').hidden = false; el('composer').hidden = !canEditWorkspace(); el('viewer-note').hidden = canEditWorkspace(); el('media-tab').hidden = false; el('campaigns-tab').hidden = !canEditWorkspace(); el('media-form').hidden = !canEditWorkspace(); switchView('workspace'); if (isAdmin || canManageWorkspace()) el('team-tab').hidden = false; el('instance-users').hidden = !isAdmin; el('workspace-members').hidden = !canManageWorkspace(); el('workspace-delete').hidden = workspaceRole !== 'owner'; el('owner-settings').hidden = workspaceRole !== 'owner'; el('billing-actions').hidden = !(workspaceRole === 'owner' && setup.deployment_mode === 'hosted'); if (canManageWorkspace()) { loadMembers(); loadInvites(); loadOverview(); } loadBrandVoice(); if (isAdmin || canManageWorkspace()) loadOrganizations(); aiScope = canManageWorkspace() ? 'workspace' : 'instance'; el('ai-scope').value = aiScope; el('ai-scope-row').hidden = !(isAdmin && canManageWorkspace()); if (isAdmin || canManageWorkspace()) { el('ai-providers-tab').hidden = false; loadAiSettings(); } if (isAdmin) { loadUsers(); } loadAiProviders(); load(); return; } el('auth').hidden = false; const creating = setup.setup_required; let signup = false; const applyAuthMode = () => { el('auth-title').textContent = creating ? 'Create administrator' : signup ? 'Create your account' : 'Sign in'; el('auth-submit').textContent = creating || signup ? 'Create account' : 'Sign in'; el('auth-toggle').textContent = signup ? 'Have an account? Sign in' : 'Need an account? Create one'; }; if (!creating && setup.self_signup) { el('auth-alt').hidden = false; el('auth-toggle').onclick = event => { event.preventDefault(); signup = !signup; applyAuthMode(); }; } applyAuthMode(); el('auth-form').onsubmit = async event => { event.preventDefault(); const endpoint = creating ? '/api/setup' : signup ? '/api/signup' : '/api/login'; const response = await fetch(endpoint, {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({username:el('username').value.trim(), password:el('password').value})}); const result = await response.json(); if (!response.ok) { el('auth-message').textContent = result.error || 'Could not sign in.'; return; } location.reload(); }; }
function renderPosts(data) {
  const posts = el('posts');
  if (!data.posts.length) { posts.replaceChildren(add('div', 'No drafts or scheduled posts yet.', 'target-empty')); return; }
  posts.replaceChildren(...data.posts.map(post => {
    const row = document.createElement('article'); row.className = 'post';
    const copy = document.createElement('div');
    copy.append(add('strong', post.body), add('span', `${post.channel}${post.scheduled_for ? ` - ${new Date(post.scheduled_for).toLocaleString()}` : ''}${post.media_urls?.length ? ` - ${post.media_urls.length} image${post.media_urls.length === 1 ? '' : 's'}` : ''}`, 'post-meta'));
    if (post.last_error) copy.append(add('span', post.last_error, 'post-error'));
    const actions = document.createElement('div'); actions.className = 'post-actions';
    const history = add('button', 'History', 'quiet'); history.onclick = async () => { const response = await api(`/api/posts/${post.id}/deliveries`); const result = await response.json(); message(response.ok ? ([...result.targets.map(target => `${target.display_name}: ${target.state}${target.last_error ? ` (${target.last_error})` : ''}`), ...result.deliveries.map(delivery => `${delivery.created_at}: ${delivery.status}`)].join(' | ') || 'No delivery attempts yet.') : (result.error || 'Could not load history.'), !response.ok); }; actions.append(history);
    if (post.state === 'published' && canEditWorkspace()) {
      const removeRemote = add('button', 'Delete from channels', 'secondary'); removeRemote.onclick = async () => { if (!confirm('Delete this published post from every connected channel? This cannot be undone.')) return; const response = await api(`/api/posts/${post.id}/delete-from-channels`, {method:'POST', headers:{'Content-Type':'application/json'}, body:'{}'}); const result = await response.json(); const detail = [...(result.deleted || []).map(name => `${name}: deleted`), ...(result.failed || []).map(item => `${item.provider}: ${item.error}`)].join(' | '); message(detail || result.error || 'No channel deleted the post.', !response.ok || (result.failed || []).length); load(); }; actions.append(removeRemote);
    } else if (!['publishing', 'deleted', 'published'].includes(post.state) && canEditWorkspace()) {
      if (post.state === 'failed') { const retry = add('button', 'Retry', 'secondary'); retry.onclick = async () => { const response = await api(`/api/posts/${post.id}/retry`, {method:'POST', headers:{'Content-Type':'application/json'}, body:'{}'}); const result = await response.json(); message(response.ok ? 'Retry queued.' : (result.error || 'Could not retry.'), !response.ok); if (response.ok) load(); }; actions.append(retry); }
      const publish = add('button', 'Publish now', 'secondary'); publish.onclick = async () => { const response = await api(`/api/posts/${post.id}/publish`, {method:'POST', headers:{'Content-Type':'application/json'}, body:'{}'}); const result = await response.json(); message(response.ok ? 'Publishing is queued.' : (result.error || 'Could not publish.'), !response.ok); if (response.ok) load(); }; actions.append(publish);
      const remove = add('button', 'Remove', 'quiet'); remove.onclick = async () => { if (!confirm('Remove this item from the queue?')) return; const response = await api(`/api/posts/${post.id}/remove`, {method:'POST', headers:{'Content-Type':'application/json'}, body:'{}'}); const result = await response.json(); message(response.ok ? 'Removed from the queue.' : (result.error || 'Could not remove post.'), !response.ok); if (response.ok) load(); }; actions.append(remove);
    }
    row.append(add('div', post.state, 'post-state'), copy, actions); return row;
  }));
}
start();
